import { PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { LoopOnce } from 'three';

export default function createNode(config, ctx) {
  const {
    scenePlacement: { position, rotation, scale },
    assets: { imageUrl },
    atlasRegion: { sourceRect }
  } = config;

  // Load texture and set sub-rectangle
  const texture = ctx.textureLoader.load(imageUrl);
  const img = texture.image;
  const imgWidth = img ? img.naturalWidth || img.width : 1;
  const imgHeight = img ? img.naturalHeight || img.height : 1;
  const [sx, sy, sw, sh] = sourceRect;
  texture.wrapS = texture.wrapT = 1000; // ClampToEdgeWrapping
  texture.repeat.set(sw / imgWidth, sh / imgHeight);
  texture.offset.set(sx / imgWidth, 1 - (sy + sh) / imgHeight); // WebGL origin top-left vs bottom-left

  // Plane geometry sized to source rect aspect ratio
  const aspect = sh / sw;
  const width = 1;
  const geometry = new PlaneGeometry(width, width * aspect);

  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: DoubleSide
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // No handlers or animations
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
